style.css:
@-moz-document domain("google.com") {
/* ====== Base Styles ====== */
  body,
  html {
    background: #0f0f0f !important;
    color: #00ffc3 !important;
    font-family: 'Orbitron', sans-serif !important;
    letter-spacing: 0.05em;
  }

  /* ====== Search Bar ====== */
  input[name="q"] {
    background: #141414 !important;
    border: 1px solid #00ffc3 !important;
    color: #00ffc3 !important;
    padding: 0.6rem 1rem !important;
    border-radius: 8px !important;
    font-weight: 500 !important;
    font-size: 16px !important;
    box-shadow: 0 0 8px #00ffc3a2 !important;
    transition: all 0.3s ease !important;
  }

  input[name="q"]:focus {
    background: #1c1c1c !important;
    box-shadow: 0 0 15px #00ffc3 !important;
  }

  /* ====== Logo Hiding or Stylizing ====== */
  img[alt="Google"] {
    filter: hue-rotate(150deg) brightness(150%);
    opacity: 0.8;
    transition: all 0.4s ease;
  }

  /* ====== Search Buttons ====== */
  input[type="submit"],
  center input[type="button"] {
    background: linear-gradient(90deg, #00ffc3, #008b6e) !important;
    border: none !important;
    border-radius: 12px !important;
    color: black !important;
    font-weight: bold !important;
    padding: 8px 16px !important;
    margin-top: 12px !important;
    box-shadow: 0 0 10px #00ffc380 !important;
    transition: transform 0.2s ease !important;
  }

  input[type="submit"]:hover {
    transform: scale(1.05) !important;
    box-shadow: 0 0 20px #00ffc3 !important;
  }

  /* ====== Links & Results ====== */
  a {
    color: #00ffc3 !important;
  }

  h3 {
    color: #ffffff !important;
    text-shadow: 0 0 3px #00ffc3 !important;
  }

  /* ====== Footer & Extras ====== */
  #fbar,
  #fbar a,
  footer {
    background: #111 !important;
    color: #00ffc3 !important;
    border-top: 1px solid #00ffc3;
  }

  /* ====== Search Results Container ====== */
  #searchform,
  #rcnt,
  #appbar {
    background-color: #0f0f0f !important;
    border-radius: 12px;
    padding: 1rem;
    margin-top: 10px;
    box-shadow: 0 0 20px #00ffc320 !important;
  }

  /* ====== Custom Cursor (Optional) ====== */
  * {
    cursor: crosshair !important;
  }
}
